const STATUS_SPINNER_FRAMES = ["|", "/", "-", "\\"] as const;
const STATUS_SPINNER_INTERVAL_MS = 80;

function colorize(code: string, text: string): string {
  return `${code}${text}${ANSI_RESET}`;
