    const frame = STATUS_SPINNER_FRAMES[this.spinnerFrame % STATUS_SPINNER_FRAMES.length];
    return [truncateToWidth(colorize(ANSI_DIM, `${frame} ${this.message}`), Math.max(1, width))];
  }
}

